import random
from itertools import combinations

def check_girth_ge6_fast(adj, u, v):
    """Check if adding edge (u,v) would NOT create a cycle of length <= 5."""
    dist = {u: 0}
    queue = [u]
    qi = 0
    while qi < len(queue):
        x = queue[qi]; qi += 1
        if dist[x] >= 4:
            continue
        for y in adj[x]:
            if y not in dist:
                dist[y] = dist[x] + 1
                queue.append(y)
    return v not in dist

def build_graph_greedy(n, seed=42):
    random.seed(seed)
    adj = [set() for _ in range(n)]
    edges = []
    all_possible = [(i,j) for i in range(n) for j in range(i+1,n)]
    random.shuffle(all_possible)
    for u, v in all_possible:
        if check_girth_ge6_fast(adj, u, v):
            adj[u].add(v)
            adj[v].add(u)
            edges.append((u,v))
    return edges

def compute_girth_check(n, edges):
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)
    min_cycle = float('inf')
    for start in range(n):
        dist = [-1] * n
        parent = [-1] * n
        dist[start] = 0
        queue = [start]
        qi = 0
        while qi < len(queue):
            u = queue[qi]; qi += 1
            for v in adj[u]:
                if dist[v] == -1:
                    dist[v] = dist[u] + 1
                    parent[v] = u
                    queue.append(v)
                elif parent[u] != v:
                    cycle_len = dist[u] + dist[v] + 1
                    if cycle_len < min_cycle:
                        min_cycle = cycle_len
    return min_cycle

# Find best greedy
best_greedy_edges = []
best_greedy_count = 0
for seed in range(500):
    edges = build_graph_greedy(15, seed)
    if len(edges) > best_greedy_count:
        best_greedy_count = len(edges)
        best_greedy_edges = edges

print(f"Best greedy: {best_greedy_count} edges")
print(f"Girth check: {compute_girth_check(15, best_greedy_edges)}")
